"""Seeded A–F data generated by the untouched AD reference, not DM stages."""
import numpy as np
import jax
import jax.numpy as jnp
from ptycho_jax.DM.geometry import make_geometry
from ptycho_jax.DM.init import make_data
from ptycho_jax.transmission.transmission_ptycho_models import construct_point_model_ptycho_transmission


def make_case(case='A',frame=64,side=10,seed=10,dtype=np.complex64):
    rng=np.random.default_rng(seed)
    modes=1 if case in ('A','B') else 3
    fractional=case in ('B','D','E','F')
    margin=4;step=max(2,frame//8);pad=4
    canvas=(frame+2*margin+(side-1)*step+2*pad,)*2
    yy,xx=np.meshgrid(np.arange(side)*step+pad,np.arange(side)*step+pad,indexing='ij')
    n=np.column_stack((yy.ravel(),xx.ravel())).astype(np.int32)
    real_dtype=np.float32 if dtype==np.complex64 else np.float64
    delta=rng.uniform(.05,.95,n.shape).astype(real_dtype) if fractional else np.zeros(n.shape,real_dtype)
    geom=make_geometry(n,delta,canvas,(frame,frame),margin)
    y,x=np.indices(canvas)
    amp=.82+.12*np.cos(x*.19)*np.cos(y*.17)
    phase=.35*np.sin(x*.13)+.2*np.cos(y*.15)+.12*np.sin((x+y)*.35)
    obj=(amp*np.exp(1j*phase)).astype(dtype)
    y,x=np.indices((frame,frame));y=y-frame/2;x=x-frame/2
    radius=frame/5
    envelope=np.exp(-(y*y+x*x)/radius**2)
    candidates=np.array([envelope,(y/radius)*envelope,(x/radius)*envelope])[:modes]
    q,_=np.linalg.qr(candidates.reshape(modes,-1).T)
    probe=q.T.reshape(modes,frame,frame).astype(dtype)
    profile=np.array([.8,.15,.05])[:modes];profile/=profile.sum()
    weights=np.broadcast_to(profile[None]*2e5,(len(n),modes)).copy()
    if case in ('D','E','F'):
        t=np.linspace(0,1,len(n))
        for k in range(modes):
            variation=.35*np.sin(2*np.pi*t+.8*k)+.2*(k-1)*(t-.5)+.04*rng.normal(size=len(n))
            weights[:,k]*=np.maximum(.1,1+variation)
    a=np.sqrt(weights).astype(real_dtype)
    model=construct_point_model_ptycho_transmission({
        'probe_type':'fluctuating','sample_type':'complex','binning_factor':(1,1),
        'sample_selector_type':'correcting','propagator_type':'Fourrier',
        'probe_shape':geom.frame_shape,'shift_margin':margin,'max_correction_magnitude':5.,
    })['point_model']
    params={'sample':jnp.asarray(obj),'probe_modes':jnp.asarray(probe),
            'modal_weights':jnp.asarray(np.eye(modes)[None]*a[:,None,:],dtype=jnp.asarray(probe).dtype),
            'scan_mistakes':jnp.arctanh(-geom.delta/5)}
    with jax.default_matmul_precision('highest'):
        truth_I=jax.vmap(model,in_axes=(None,None,0))(params,{'sample_positions':geom.n},jnp.arange(len(n)))
    intensities=np.asarray(truth_I)
    if case=='E':intensities=rng.poisson(np.maximum(intensities,0)).astype(real_dtype)
    data=make_data(intensities,np.ones((frame,frame),bool),dtype=real_dtype)
    guess=probe[0]*np.exp(.3j*(x*x+y*y)/radius**2)
    return {'geom':geom,'probe':jnp.asarray(probe),'obj':jnp.asarray(obj),'a':jnp.asarray(a),
            'data':data,'truth_intensity':truth_I,'probe_guess':guess.astype(dtype),'case':case,'seed':seed}
